// Kind of campaign. `TEN_DIGIT_LONG_CODE` is a standard 10DLC campaign (the default on create) and `TOLL_FREE_UNIFIED_NUMBER` is a toll-free verification created with `POST /10dlc/campaigns/toll-free`. The other values are registry campaign types you can request on create.
type CampaignCampaignType string

const (
	CampaignCampaignTypeTenDigitLongCode           CampaignCampaignType = "TEN_DIGIT_LONG_CODE"
	CampaignCampaignTypeTollFreeUnifiedNumber      CampaignCampaignType = "TOLL_FREE_UNIFIED_NUMBER"
	CampaignCampaignTypeTollFreeNumber             CampaignCampaignType = "TOLL_FREE_NUMBER"
	CampaignCampaignTypeShortCode                  CampaignCampaignType = "SHORT_CODE"
	CampaignCampaignTypeExternalTenDigitLongCode   CampaignCampaignType = "EXTERNAL_TEN_DIGIT_LONG_CODE"
	CampaignCampaignTypeDca2TenDigitLongCode       CampaignCampaignType = "DCA2_TEN_DIGIT_LONG_CODE"
	CampaignCampaignTypeTollFreeExternallyVerified CampaignCampaignType = "TOLL_FREE_EXTERNALLY_VERIFIED"
	CampaignCampaignTypeRcsSenderLaunch            CampaignCampaignType = "RCS_SENDER_LAUNCH"
)

func NewCampaignCampaignTypeFromString(s string) (CampaignCampaignType, error) {
	switch s {
	case "TEN_DIGIT_LONG_CODE":
		return CampaignCampaignTypeTenDigitLongCode, nil
	case "TOLL_FREE_UNIFIED_NUMBER":
		return CampaignCampaignTypeTollFreeUnifiedNumber, nil
	case "TOLL_FREE_NUMBER":
		return CampaignCampaignTypeTollFreeNumber, nil
	case "SHORT_CODE":
		return CampaignCampaignTypeShortCode, nil
	case "EXTERNAL_TEN_DIGIT_LONG_CODE":
		return CampaignCampaignTypeExternalTenDigitLongCode, nil
	case "DCA2_TEN_DIGIT_LONG_CODE":
		return CampaignCampaignTypeDca2TenDigitLongCode, nil
	case "TOLL_FREE_EXTERNALLY_VERIFIED":
		return CampaignCampaignTypeTollFreeExternallyVerified, nil
	case "RCS_SENDER_LAUNCH":
		return CampaignCampaignTypeRcsSenderLaunch, nil
	}
	var t CampaignCampaignType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

